__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"default",{enumerable:!0,get:function(){return s}});var o=r(d[0]),t=r(d[1]),n=r(d[2]);function s(){const s=(0,o.c)(9);let l,c,h,u,y,p,f,v,w;return s[0]===Symbol.for("react.memo_cache_sentinel")?(l={heading:"Who runs SevaSetu",paragraphs:[`SevaSetu is operated by Harshil Vanani for volunteer seva organized with The Art of Living community. Contact us at ${t.CONTACT_EMAIL}.`]},s[0]=l):l=s[0],s[1]===Symbol.for("react.memo_cache_sentinel")?(c={heading:"What we collect",bullets:["Account: your name, email address and how you sign in (email and password, or Google). If you use Google, Google shares your name, email and profile photo with us. Passwords are stored only in encrypted form by our authentication provider.","Profile details you choose to add: city or area, your approximate location if you allow it (to show distances), how far you will travel, interests, skills, weekly availability, how you like to serve, hours per week and language.","Your seva activity: the seva you join, the quantity you take on, the progress you report and notes you write, organizers\u2019 reviews of your reports (including any adjustment and its reason), invitations, and in-app notifications.","If you organize: your organization\u2019s name, city and description, and the events and tasks you publish.","If you allow notifications on a phone: a push notification token for that device."]},s[1]=c):c=s[1],s[2]===Symbol.for("react.memo_cache_sentinel")?(h={heading:"How we use it",bullets:["To show you seva that fits your interests, location and availability.","To let you join seva, report progress, and receive confirmations, reminders and updates.","To let organizers coordinate the seva you take part in and verify the work reported.","To keep SevaSetu safe: reviewing new organizations and stopping misuse."],paragraphs:["We do not sell your information, show ads, or use advertising or analytics trackers."]},s[2]=h):h=s[2],s[3]===Symbol.for("react.memo_cache_sentinel")?(u={heading:"Who can see your information",bullets:["Organizers of a seva you join or are invited to can see your name, email address and profile details, and your joins, progress reports and notes for their seva.","Other volunteers do not see your contact details.","SevaSetu administrators can see account information, organizations and activity to review organizations and keep the platform safe. Their actions are recorded in an audit log.","Anyone, even without an account, can see public seva listings and the name of the organization running them."]},s[3]=u):u=s[3],s[4]===Symbol.for("react.memo_cache_sentinel")?(y={heading:"Services we use",bullets:["Supabase stores the app\u2019s data and handles sign-in. Data is held in the United States (Oregon).","Hostinger hosts the SevaSetu website.","Google provides \u201cContinue with Google\u201d sign-in, if you choose it.","Expo delivers push notifications to phones that allow them."],paragraphs:["These providers process information only to run their part of the service."]},s[4]=y):y=s[4],s[5]===Symbol.for("react.memo_cache_sentinel")?(p={heading:"How long we keep it",paragraphs:["We keep your information while your account exists. You can delete your account at any time in Profile \u2192 Delete account. This permanently removes your profile, availability, seva history, progress reports and notifications. If you are the only owner of an organization, add another owner or delete the organization first.","If an administrator acted on your account or organization, the audit log keeps a short record of that action, with your name, for safety reasons."]},s[5]=p):p=s[5],s[6]===Symbol.for("react.memo_cache_sentinel")?(f={heading:"Your choices",bullets:["Edit your profile, interests and availability at any time in the app.","Location is optional: you can type a city instead, or nothing at all.","Turn push notifications on or off in your phone\u2019s settings.",`Ask for a copy of your information, or for corrections, by writing to ${t.CONTACT_EMAIL}.`]},s[6]=f):f=s[6],s[7]===Symbol.for("react.memo_cache_sentinel")?(v={heading:"Children",paragraphs:["SevaSetu is not meant for children under 16 without the involvement of a parent or guardian, who should create and manage the account."]},s[7]=v):v=s[7],s[8]===Symbol.for("react.memo_cache_sentinel")?(w=(0,n.jsx)(t.LegalPage,{title:"Privacy Policy",intro:`SevaSetu helps volunteers find and join seva (selfless service) and helps organizations coordinate it. This policy explains what information SevaSetu keeps, why, who can see it, and the choices you have. Questions: ${t.CONTACT_EMAIL}.`,sections:[l,c,h,u,y,p,f,v,{heading:"Changes to this policy",paragraphs:["If we change this policy, we will update the date at the top. Significant changes will be announced in the app."]}]}),s[8]=w):w=s[8],w}},793,[806,1007,6]);